import numpy as np
b=np.load('data/bands_n9491.npz')['L17_N9491'].astype(np.float32)[:1500]
T=np.load('data/corpus.npz')['tokens'][:1500]
pm=8.1875
f=b/pm
# for each window, compute run-length of match: k such that tokens [P-k+1..P+1] appeared earlier as contiguous span
cats={}
for W in range(1500):
    t=T[W].tolist(); seen={}
    first={}
    for i in range(len(t)-1):
        first.setdefault((t[i],t[i+1]),i)
    for P in range(64,1022):
        bg=(t[P],t[P+1])
        if first.get(bg,9999)>=P: c='novel_next'
        else:
            j=first[bg]
            # was previous bigram also a repeat at aligned position?
            if j>0 and t[j-1]==t[P-1] and (t[P-1],t[P]) in first and first[(t[P-1],t[P])]<P-1:
                c='inside_repeat'
            else: c='repeat_onset'
        cats.setdefault(c,[]).append(f[W,P])
for c,v in cats.items():
    v=np.array(v); print(f'{c:14} n={len(v):7d} mean={v.mean():.3f} p(>0.2)={np.mean(v>0.2):.4f} p(>0.3)={np.mean(v>0.3):.5f}')
"

